solution_code:
#include <iostream>

class Percent {
    int m_value;
public:
    explicit Percent(int value) : m_value{value} {}
    int value() const { return m_value; }
    int of(int total) const { return m_value * total / 100; }
};

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int p, total;
        std::cin >> p >> total;
        Percent pct{p};
        std::cout << pct.value() << "% of " << total << " = " << pct.of(total) << "\n";
    }
}

