#include <iostream>

struct Celsius {
    int degrees;
    Celsius(int d) : degrees{d} {}
};

struct Fahrenheit {
    int degrees;
    explicit Fahrenheit(int d) : degrees{d} {}
};

void report(Celsius c) { std::cout << "Celsius " << c.degrees << "\n"; }
void report(Fahrenheit f) { std::cout << "Fahrenheit " << f.degrees << "\n"; }

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int x;
        std::cin >> x;
        report(x);
    }
}
